package inventory

import "errors"

// Item is one stocked product.
type Item struct {
	SKU      string
	Name     string
	Quantity int
}

// Store keeps items by SKU.
type Store interface {
	Put(item Item) error
	Get(sku string) (Item, error)
}

// ErrUnknownSKU is returned by Get for a SKU that was never Put.
var ErrUnknownSKU = errors.New("inventory: unknown sku")

// MemoryStore is a Store backed by a map.
type MemoryStore struct {
	items map[string]Item
}

// NewMemoryStore returns an empty MemoryStore.
func NewMemoryStore() *MemoryStore {
	return &MemoryStore{items: map[string]Item{}}
}

func (s *MemoryStore) Put(item Item) error {
	s.items[item.SKU] = item
	return nil
}

func (s *MemoryStore) Get(sku string) (Item, error) {
	item, ok := s.items[sku]
	if !ok {
		return Item{}, ErrUnknownSKU
	}
	return item, nil
}
